async function getPostsWithAuthors(db) {
  const posts = await db.query('SELECT * FROM posts');

  for (let post of posts) {
    const author = await db.query('SELECT * FROM users WHERE id = ?', [post.authorId]);
    post.author = author[0];
  }

  return posts;
}

